import { APU_SAMPLE_RATE } from '../core/sound';
import { SincResampler } from './audioResampler';

export interface AudioSource { drainSamples(): number[] }

/** Bounded transport queue for samples generated by a worker's native APU. */
export class AudioSampleQueue implements AudioSource {
  private samples: number[] = [];
  push(samples: ArrayLike<number>): void {
    for (let i = Math.max(0, samples.length - APU_SAMPLE_RATE); i < samples.length; i++) this.samples.push(samples[i]!);
    if (this.samples.length > APU_SAMPLE_RATE) this.samples.splice(0, this.samples.length - APU_SAMPLE_RATE);
  }
  drainSamples(): number[] { const samples = this.samples; this.samples = []; return samples; }
  reset(): void { this.samples = []; }
}

type AudioContextCtor = new () => AudioContext;

export class AudioOutput {
  private ctx: AudioContext | null = null;
  private node: ScriptProcessorNode | null = null;
  private resampler: SincResampler | null = null;
  private queue: number[] = [];
  /** Optional browser playback failures must not stop emulation. */
  error: string | null = null;

  private reportError(error: unknown): void {
    this.error = error instanceof Error ? error.message : String(error);
  }

  start(device: AudioSource): void {
    const Ctor = window.AudioContext as AudioContextCtor | undefined;
    if (!Ctor) { this.error = 'Browser audio is unavailable.'; return; }
    try {
      if (!this.ctx) {
        this.ctx = new Ctor();
        this.resampler = new SincResampler(this.ctx.sampleRate);
        this.node = this.ctx.createScriptProcessor(1024, 0, 1);
        this.node.onaudioprocess = (e) => this.fill(e, device);
        this.node.connect(this.ctx.destination);
      }
    } catch (error) {
      this.reportError(error);
      // Dispose partially initialized playback so the next Run can retry.
      if (this.node) {
        this.node.onaudioprocess = null;
        try { this.node.disconnect(); } catch { /* Already disconnected. */ }
      }
      try { void this.ctx?.close().catch(() => {}); } catch { /* Already closed. */ }
      this.ctx = null;
      this.node = null;
      this.resampler = null;
      this.queue.length = 0;
      return;
    }
    try {
      void this.ctx.resume().then(() => { this.error = null; }, (error: unknown) => this.reportError(error));
    } catch (error) {
      this.reportError(error);
    }
  }

  pause(): void {
    try {
      void this.ctx?.suspend().catch((error: unknown) => this.reportError(error));
    } catch (error) {
      this.reportError(error);
    }
  }

  dispose(): void {
    if (this.node) {
      this.node.onaudioprocess = null;
      try { this.node.disconnect(); } catch { /* Already disconnected. */ }
    }
    try { void this.ctx?.close().catch(() => {}); } catch { /* Already closed. */ }
    this.node = null; this.ctx = null; this.resampler = null; this.queue.length = 0;
  }

  reset(): void {
    this.queue.length = 0;
    this.resampler = this.ctx ? new SincResampler(this.ctx.sampleRate) : null;
  }

  private fill(e: AudioProcessingEvent, device: AudioSource): void {
    const fresh = this.resampler?.process(device.drainSamples()) ?? new Float32Array();
    for (let i = 0; i < fresh.length; i++) this.queue.push(fresh[i]!);

    const out = e.outputBuffer.getChannelData(0);
    // Fast emulation can produce audio faster than real-time playback. Keep
    // recent output within 100ms instead of accumulating latency indefinitely.
    const limit = Math.max(out.length, Math.ceil((this.ctx?.sampleRate ?? 0) / 10));
    if (this.queue.length > limit) this.queue.splice(0, this.queue.length - limit);
    const count = Math.min(out.length, this.queue.length);
    for (let i = 0; i < count; i++) out[i] = this.queue[i]!;
    out.fill(0, count);
    this.queue.splice(0, count);
  }
}
